Method.Source:
/// <summary>
/// Cycles tmpInventTransMark records and adjusts marked qty if related to current ProdId
/// </summary>
public void avaUpdateTmpTrans()
{
    TmpInventTransMark avaInventTransMark = TmpInventTransMark_ds.getFirst() as TmpInventTransMark;
    Qty avaQtyMax;

    try
    {
        if(avaInventTransMark)
        {
            while(avaInventTransMark)
            {
                if(avaInventTransMark.AVAInventTransOriginId == InventTransOrigin.RecId)
                {
                    if (inventTrans.Qty < 0)
                    {
                        avaQtyMax = min(avaInventTransMark.QtyRemain,-inventTrans_ds.qtyRemain(inventTrans));
                    }
                    else
                    {
                        avaQtyMax = min(-avaInventTransMark.QtyRemain,inventTrans_ds.qtyRemain(inventTrans));
                        avaQtyMax = - avaQtyMax;
                    }

                    avaInventTransMark.QtyMarkNow   = avaQtyMax;
                    avaInventTransMark.QtyRemain    = avaInventTransMark.QtyRemain - avaQtyMax;

                    if (mapMarkNow.exists(avaInventTransMark.RecId))
                    {
                        mapMarkNow.remove(avaInventTransMark.RecId);
                    }

                    if(avaQtyMax != 0)
                    {
                        mapMarkNow.insert(avaInventTransMark.RecId,avaInventTransMark);
                    }

                    this.updateMarking();

                    avaInventTransMark.qtyMarkNow   = 0;
                    avaInventTransMark.QtyMarked    = avaInventTransMark.QtyMarked + avaQtyMax;

                    if (mapMarkNow.exists(avaInventTransMark.RecId))
                    {
                        mapMarkNow.remove(avaInventTransMark.RecId);
                    }
                }

                avaInventTransMark = TmpInventTransMark_ds.getNext() as TmpInventTransMark;

            }
        }

    }
    catch
    {
    }
}
